  <div class="app">
    <section class="auth-screen" id="authView" aria-live="polite">
      <div class="auth-card">
        <div class="auth-header">
          <div class="brand">
            <span class="brand-mark" aria-hidden="true"></span>
            <div>
              <p>Sign in to collaborate with your tutor.</p>
            </div>
          </div>
        </div>
        <div class="auth-tabs" role="tablist">
          <button class="auth-tab is-active" id="tabSignIn" type="button" role="tab">Sign In</button>
          <button class="auth-tab" id="tabSignUp" type="button" role="tab">Sign Up</button>
          <button class="auth-tab" id="tabConfirm" type="button" role="tab">Confirm</button>
        </div>
        <div class="auth-panel" id="panelSignIn" role="tabpanel">
          <form id="signInForm">
            <label>
              Email
              <input id="signInEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Password
              <input id="signInPassword" type="password" autocomplete="current-password" required />
            </label>
            <button type="submit">Sign In</button>
            <button class="link-button" type="button" id="forgotPassword">Forgot password?</button>
            <button class="link-button" type="button" id="needConfirm">Need a confirmation code?</button>
          </form>
        </div>
        <div class="auth-panel" id="panelSignUp" role="tabpanel" hidden>
          <form id="signUpForm">
            <label>
              First Name
              <input id="signUpGivenName" type="text" autocomplete="given-name" maxlength="100" required />
            </label>
            <label>
              Last Name
              <input id="signUpFamilyName" type="text" autocomplete="family-name" maxlength="100" required />
            </label>
            <label>
              Date of birth
              <input id="signUpBirthDate" type="date" autocomplete="bday" required />
            </label>
            <label>
              Email
              <input id="signUpEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Password
              <input id="signUpPassword" type="password" autocomplete="new-password" required />
            </label>
            <button type="submit">Create Account</button>
          </form>
        </div>
        <div class="auth-panel" id="panelConfirm" role="tabpanel" hidden>
          <form id="confirmForm">
            <label>
              Email
              <input id="confirmEmail" type="email" autocomplete="email" required />
            </label>
            <label>
              Confirmation Code
              <input id="confirmCode" type="text" inputmode="numeric" autocomplete="one-time-code" required />
            </label>
            <button type="submit">Confirm Account</button>
            <button class="secondary" type="button" id="resendCode">Resend Code</button>
          </form>
        </div>
        <div class="auth-panel" id="panelForgot" role="tabpanel" hidden>
          <form id="forgotPasswordForm">
            <label>
              Email
              <input id="forgotEmail" type="email" autocomplete="email" required />
            </label>
            <button type="button" id="requestResetCode">Send reset code</button>
            <label>
              Reset code
              <input id="forgotCode" type="text" inputmode="numeric" autocomplete="one-time-code" />
            </label>
            <label>
              New password
              <input id="forgotNewPassword" type="password" autocomplete="new-password" />
            </label>
            <label>
              Confirm new password
              <input id="forgotConfirmPassword" type="password" autocomplete="new-password" />
            </label>
            <button type="submit">Reset password</button>
            <button class="secondary" type="button" id="backToSignIn">Back to Sign In</button>
          </form>
        </div>
        <div class="auth-panel" id="panelResetRequired" role="tabpanel" hidden>
          <form id="resetRequiredForm">
            <label>
              Email
              <input id="resetRequiredEmail" type="email" autocomplete="email" readonly />
            </label>
            <label>
              New password
              <input id="resetRequiredNewPassword" type="password" autocomplete="new-password" required />
            </label>
            <label>
              Confirm new password
              <input id="resetRequiredConfirmPassword" type="password" autocomplete="new-password" required />
            </label>
            <button type="submit">Set new password</button>
            <button class="secondary" type="button" id="resetRequiredBack">Back to Sign In</button>
          </form>
        </div>
        <div class="auth-message" id="authMessage" role="status"></div>
      </div>
    </section>
    <section class="board-screen" id="boardView" hidden>
      <div id="whiteboardAppBarContainer"></div>
      <main class="board-layout">
        <aside class="board-left-rail" aria-label="PDF pages">
          <div class="pdf-sidebar-toolbar" id="pdfSidebarToolbar" hidden>
            <button type="button" class="pdf-sidebar-mode is-active" id="pdfSidebarModePage">Pages</button>
            <button type="button" class="pdf-sidebar-mode" id="pdfSidebarModeQuestion">Questions</button>
          </div>
          <div class="pdf-sidebar" id="pdfSidebar" hidden></div>
        </aside>
        <section class="board-center">
          <div class="board" id="boardStage">
            <div class="connection-error" id="connectionError" role="alert" hidden></div>
            <div class="offline-indicator" id="offlineIndicator" role="status" hidden>
              <span class="offline-icon" aria-hidden="true">⚠</span>
              <span class="offline-text">Sync paused while working offline</span>
            </div>
            <div class="stroke-loading" id="strokeLoading" role="status" aria-live="polite" hidden>
              <div class="stroke-loading-card">
                <span class="stroke-loading-spinner" aria-hidden="true"></span>
                <span class="stroke-loading-text" id="strokeLoadingLabel">Loading…</span>
              </div>
            </div>
            <div class="pdf-layer" id="pdfLayer" aria-hidden="true">
              <div class="pdf-viewer" id="pdfViewer" hidden>
                <div
                  id="pdfVersionOverlay"
                  class="pdf-version-overlay"
                  hidden
                ></div>
                <div class="pdf-page-spread" id="pdfPageSpread">
                  <canvas id="pdfCanvas" aria-label="PDF page"></canvas>
                  <canvas
                    id="pdfCanvasSecondary"
                    aria-label="Next PDF page preview"
                    hidden
                  ></canvas>
                </div>
              </div>
            </div>
            <canvas id="board" role="img" aria-label="Drawing board"></canvas>
            <button
              class="worksheet-edit-close-btn pdf-overlay-clear-btn"
              id="pdfClear"
              type="button"
              aria-label="Clear selected PDF"
              title="Clear selected PDF"
              hidden
            >
              ×
            </button>
            <div class="lasso-action-menu" id="lassoActionMenu" hidden>
              <button type="button" id="lassoActionMove">Move</button>
              <button type="button" id="lassoActionDuplicate">Duplicate</button>
              <button type="button" id="lassoActionResize">Resize</button>
              <button type="button" id="lassoActionConvertToStrokes">Image → Strokes</button>
              <button type="button" id="lassoActionCut">Cut</button>
              <button type="button" id="lassoActionCopy">Copy</button>
              <button type="button" id="lassoActionDelete">Delete</button>
            </div>
            <div class="lasso-action-menu" id="lassoPasteMenu" hidden>
              <button type="button" id="lassoPasteConfirm">Paste</button>
              <button type="button" id="lassoPasteCancel">Cancel</button>
            </div>
            <div class="lasso-action-menu pdf-thumb-action-menu" id="pdfThumbActionMenu" hidden>
              <button type="button" id="pdfThumbActionDelete">Delete</button>
            </div>
            <div id="eraserIndicator" class="eraser-indicator" hidden></div>
            <div class="student-panel" id="studentPanel" hidden>
              <div class="student-panel-header">
                <div>
                  <h2>Students</h2>
                  <p>Select students to work with</p>
                </div>
                <button class="student-panel-close" id="studentClose" type="button" aria-label="Close student list">×</button>
              </div>
              <div class="student-panel-search">
                <input id="studentSearchInput" type="search" placeholder="Search by name or email" />
              </div>
              <div class="student-panel-status" id="studentStatus"></div>
              <button class="student-panel-clear" id="studentClear" type="button" hidden>Clear Students</button>
              <div class="student-results" id="studentResults"></div>
            </div>
            <div class="observer-panel" id="observerPanel" hidden>
              <div class="observer-panel-header">
                <div>
                  <h2>Sessions</h2>
                  <p>Open any session in read-only observer mode</p>
                </div>
                <button class="observer-panel-close" id="observerClose" type="button" aria-label="Close sessions">×</button>
              </div>
              <div class="observer-panel-search">
                <input id="observerSearchInput" type="search" placeholder="Search by participant email or session ID" />
              </div>
              <div class="observer-panel-status" id="observerStatus"></div>
              <div class="observer-results" id="observerResults"></div>
            </div>
            <div class="pdf-panel" id="pdfPanel" hidden>
              <div class="pdf-panel-header">
                <div>
                  <h2>PDF Library</h2>
                  <p>Search the Cambridge papers index</p>
                </div>
                <button class="pdf-panel-close" id="pdfClose" type="button" aria-label="Close PDF search">×</button>
              </div>
              <div class="pdf-panel-search">
                <input id="pdfSearchInput" type="search" placeholder="Search by filename, year, or session" />
              </div>
              <div class="pdf-panel-filters">
                <div class="pdf-panel-filter-row pdf-panel-filter-row-tutor">
                  <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterALevelsLabel" hidden>
                    <input type="checkbox" id="filterALevels" checked />
                    <span>A-Levels</span>
                  </label>
                  <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterASLabel" hidden>
                    <input type="checkbox" id="filterAS" checked />
                    <span>AS</span>
                  </label>
                  <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterIGExtLabel" hidden>
                    <input type="checkbox" id="filterIGExt" checked />
                    <span>IG Ext</span>
                  </label>
                  <label class="pdf-filter-checkbox pdf-filter-tutor-only" id="filterIGCoreLabel" hidden>
                    <input type="checkbox" id="filterIGCore" checked />
                    <span>IG Core</span>
                  </label>
                </div>
                <div class="pdf-panel-filter-row pdf-panel-filter-row-docs">
                  <label class="pdf-filter-checkbox" id="filterWSLabel">
                    <input type="checkbox" id="filterWS" />
                    <span>WS</span>
                  </label>
                  <label class="pdf-filter-checkbox" id="filterQPLabel">
                    <input type="checkbox" id="filterQP" checked />
                    <span>QP</span>
                  </label>
                  <label class="pdf-filter-checkbox" id="filterMSLabel">
                    <input type="checkbox" id="filterMS" />
                    <span>MS</span>
                  </label>
                  <label class="pdf-filter-checkbox" id="filterNotesLabel">
                    <input type="checkbox" id="filterNotes" />
                    <span>Notes</span>
                  </label>
                </div>
              </div>
              <div class="pdf-panel-status" id="pdfStatus"></div>
              <div class="pdf-results" id="pdfResults"></div>
            </div>
            <div class="observer-banner" id="observerBanner" hidden>
              <span class="observer-banner-text" id="observerBannerText"></span>
              <button
                class="observer-banner-copy"
                id="observerBannerCopy"
                type="button"
                aria-label="Copy session ID"
                title="Copy session ID"
              >
                ID
              </button>
              <button
                class="observer-banner-exit"
                id="observerBannerExit"
                type="button"
                aria-label="Exit observer mode"
              >
                ×
              </button>
            </div>
          </div>
        </section>
        <aside class="board-right-rail" aria-label="Editing tools">
          ${lm()}
        </aside>
      </main>
    </section>
  </div>
